CAST=[['拉丁 castus 纯净的、贞洁的','古代道德与宗教语汇；不是给现代人的价值分等级']]
CHASTE=CAST+[['古法语 chaste → 中古英语 chaste → chaste','贞洁的；后来也形容表达与风格克制、朴素']]
CASTIG=CAST+[['拉丁 castigare 纠正、惩戒','castus + 与 agere 做相关的成分：以纠正使其符合规范']]
CHAST=CASTIG+[['古法语 chastiier → 中古英语 chastien / chastisen','惩戒、责备；chastise 的具体词尾形成尚有疑问']]
CHASTEN=CHAST+[['英语旧动词 chaste + -en → chasten','使受到教训、收敛傲气；不是直接把现代形容词 chaste 变成动词']]
CASTR=[['拉丁 castrare 阉割、修剪','与 castus 的更远关系不能仅凭近形断定']]
TER=[['拉丁 terere 摩擦、磨损；分词词干 trit-','磨去实物，或比喻消耗力量、磨掉新鲜感']]
DETR=TER+[['拉丁 deterere 磨掉 → detrimentum 损失、损害','de- 离去 + terere：磨掉一部分，因而有所损失'],['古法语 détriment 或直接拉丁借入 → 英语 detriment','损害；不利影响']]
CONTR=TER+[['拉丁 conterere 磨碎 → contritus 磨碎的；悔罪的','con- 与 terere 组合；宗教语境用内心被压碎比喻深切悔意']]
CONTRITE=CONTR+[['古法语 contrit 或直接拉丁借入 → 英语 contrite','因自己做错事而懊悔']]
LONG=[['拉丁 longus 长的、远的','这条拉丁线与英语本族词 long 的日耳曼线分开']]
PRO=LONG+[['晚期拉丁 prolongare 延长','pro- 向前 + longus 长：让持续范围往前伸']]
ELONG=LONG+[['晚期拉丁 elongare 拉长、移远；elongatus','e-/ex- 向外 + 长、远的词干']]
LONGIT=LONG+[['拉丁 longitudo 长度，词干 longitudin-','由长的性质构成抽象名词']]
W=[
E('caste','英 /kɑːst/；美 /kæst/','种姓；固定的社会阶层','像一个按出身分配的位置：人还没有做什么，社会就先给他划好了圈。','借葡萄牙语 casta 血统、类别、种姓。传统说法联系拉丁 castus，但更早来源有争议；不能把血统纯净的旧解释当成已经证实的历史。',[['葡萄牙语 casta 血统、类别、世袭社会群体','更远词源未定；与拉丁 castus 的联系属于传统解释'],['英语 caste','种姓；后来也比喻界限牢固的社会阶层']],'caste system 是种姓制度；caste discrimination 是基于种姓的歧视。这个词描述一种社会分类制度，不说明不同群体有天生高低之分。','the caste system；caste discrimination；caste barriers。','class 可按经济、职业等区分社会阶层；caste 尤其让人想到出身与较难跨越的群体界限。cast 投掷、选角另有来源。',('The novel follows a family confronting caste discrimination.','小说描写一个家庭面对种姓歧视的经历。'),('The essay examines how education can challenge caste barriers.','这篇文章探讨教育如何挑战种姓壁垒。'),sources=['https://www.merriam-webster.com/dictionary/caste','https://en.wiktionary.org/wiki/caste#English']),
E('chaste','/tʃeɪst/','贞洁的；不含情色意味的；朴素克制的','核心是有所克制：在旧道德语境里指性行为，在文风或装饰里指不铺张。','经古法语 chaste 借入，接拉丁 castus 纯净、贞洁。今天的几个义项是历史语义扩展，不用字面纯净去评判人的价值。',CHASTE,'a chaste kiss 通常是没有明显情色意味的轻吻；a chaste style 可指朴素节制的风格。贞洁义常出现在历史、宗教或较旧式表达中。','remain chaste；a chaste kiss；a chaste style。','celibate 常说独身、不发生性行为；chaste 的传统含义还可包括婚内忠贞，并非任何语境都等于从未有过性行为。',('The characters exchange a chaste kiss at the end of the film.','电影结尾，人物轻轻一吻，没有明显情色意味。'),('The chapel is known for its chaste architectural style.','这座小教堂以朴素克制的建筑风格著称。'),sources=['https://www.etymonline.com/word/chaste','https://www.oxfordlearnersdictionaries.com/definition/english/chaste']),
E('chastity','/ˈtʃæstəti/','贞洁；性方面的节制','把传统语境中的贞洁当成一种承诺或生活要求来谈。','拉丁 castitas，经古法语 chasteté、中古英语 chastite 进入英语；现代可联系 chaste + -ity，但它不是在现代英语中才这样拼出的词。',CAST+[['拉丁 castitas → 古法语 chasteté → 中古英语 chastite → chastity','贞洁、节制这一抽象性质']],'a vow of chastity 是守贞誓愿；不同历史和宗教语境对其要求并不完全相同。它是名词，不能用来直接修饰 person 代替 chaste。','a vow of chastity；the ideal of chastity；religious chastity。','virginity 指从未有过性行为的状态；chastity 是较广的道德或宗教节制概念，不能简单画等号。',('The historian explains what the vow of chastity meant in that community.','历史学家解释了守贞誓愿在那个群体中的含义。'),('The poem questions the different standards of chastity imposed on men and women.','这首诗质疑对男女施加的不同贞洁标准。'),sources=['https://www.etymonline.com/word/chastity','https://en.wiktionary.org/wiki/chastity#English']),
E('incest','/ˈɪnsest/','乱伦','指近亲之间的性关系；这个词的历史名称来自对禁忌关系的评价。','拉丁 in- 不 + castus 贞洁，形成 incestus；其中性名词 incestum 经古法语 inceste 或直接拉丁路线借入英语。',CAST+[['拉丁 incestus 不贞洁的 → incestum','较广的不洁、违禁义，也特指近亲性关系'],['古法语 inceste 与拉丁借入线 → 英语 incest','近亲之间的性关系']],'现代 incest 已是一个明确的关系名称，不能按字面不贞洁把所有不忠行为都叫 incest。通常是不可数名词。','the incest taboo；a discussion of incest；a case of incest。','adultery 主要涉及婚姻不忠；incest 关键在亲属关系，两词关注的不是同一条界线。',('The lecture examines the incest taboo in ancient myths.','讲座考察古代神话中的乱伦禁忌。'),('The novel discusses incest without describing it graphically.','这部小说讨论了乱伦，但没有作露骨描写。'),sources=['https://www.etymonline.com/word/incest','https://en.wiktionary.org/wiki/incest#English']),
E('incestuous','/ɪnˈsestʃuəs/','乱伦的；圈子封闭、关系过密的','本义关乎近亲关系；比喻时说一个圈子只跟自己人来往、互相交换利益或意见。','借晚期拉丁 incestuosus，接 incestus；现代可用 incest + -uous 辅助识别，但历史上是已有拉丁形容词的借入。',CAST+[['拉丁 incestus → 晚期拉丁 incestuosus → 英语 incestuous','近亲性关系的性质；后来比喻过分封闭的圈子']],'an incestuous relationship 可指本义；an incestuous professional circle 则批评圈子封闭。比喻用法带强烈贬义，不是普通熟人多。','an incestuous relationship；an incestuous circle；incestuous links。','close-knit 可以正面形容紧密团结；incestuous 的圈子义在批评排外和过度内部循环，不能当温和同义词。',('The play centres on an incestuous relationship in a royal family.','这部戏围绕一个王室家庭中的乱伦关系展开。'),('The reviewer described the awards scene as small and incestuous.','评论者说那个奖项圈子规模小，而且过分封闭。'),sources=['https://www.etymonline.com/word/incestuous','https://www.oxfordlearnersdictionaries.com/definition/english/incestuous']),
E('castigation','/ˌkæstɪˈɡeɪʃən/','严厉批评；斥责','不是轻轻提醒一句，而是把问题重重指出来，让被批评者很难回避。','来自拉丁 castigatio，接 castigare 纠正、惩戒；英语名词的记录早于动词 castigate，现代形态对应不等于历史由英语动词派生。',CASTIG+[['拉丁 castigatio → 中古英语 castigacioun → castigation','惩戒、纠正 → 现代常见严厉批评义']],'public castigation 是公开斥责；a castigation of a policy 是对政策的严厉抨击。它很正式，日常通常说 harsh criticism。','public castigation；a scathing castigation；castigation of a policy。','criticism 可以冷静分析；castigation 强调严厉责难，往往带公开施压的力度。',('The report amounted to a public castigation of the board.','这份报告等于对董事会的一次公开痛批。'),('Her essay offers a sharp castigation of the policy.','她的文章严厉抨击了这项政策。'),sources=['https://www.etymonline.com/word/castigation','https://www.oxfordlearnersdictionaries.com/definition/english/castigation']),
E('chastise','/tʃæˈstaɪz/','严厉责备；惩戒','抓住对方做错的事，明确地训斥，希望他改正。','接古法语 chastiier，远源拉丁 castigare；现代 -ise 的具体形成尚不完全清楚，也有中古英语旧动词加后缀的解释。',CHAST+[['中古英语 chastisen → chastise','惩戒、责罚；今天常用作严厉批评']],'chastise someone for something 是因某事责备某人。现代新闻中常是言语斥责；旧文献中也可能包括身体惩罚，需看语境。','chastise somebody for；publicly chastise；chastise yourself。','scold 是日常训斥；chastise 更正式。chasten 更强调受到教训后的收敛，而非谁说了重话。',('The editor chastised the reporter for skipping the fact check.','编辑责备记者省去了事实核查。'),('She chastised herself for making the same mistake again.','她责怪自己又犯了同样的错误。'),sources=['https://www.etymonline.com/word/chastise','https://en.wiktionary.org/wiki/chastise#English']),
E('chastisement','/tʃæˈstaɪzmənt/，也读 /ˈtʃæstɪzmənt/','责罚；训斥；惩戒','把责备或惩罚这件事单独提出来说：一次教训，或一种惩戒方式。','chastise + -ment；英语中古时期已见名词，保留较早责罚义，后来也用于言语斥责。',CHAST+[['英语 chastise + -ment → chastisement','惩戒这一行为或结果']],'a public chastisement 可以是公开训斥；历史文本中的 corporal chastisement 指体罚。它的语体较正式、偏旧，不能每次都译成挨打。','public chastisement；verbal chastisement；fear of chastisement。','chastise 是动作，chastisement 是相应名词；criticism 的语气一般比它轻，且未必含处罚意味。',('The manager delivered a sharp verbal chastisement.','经理作了一番严厉训斥。'),('The memoir describes a childhood shaped by fear of chastisement.','这部回忆录描写了一个因害怕责罚而深受影响的童年。'),sources=['https://www.etymonline.com/word/chastisement','https://www.oxfordlearnersdictionaries.com/definition/english/chastisement']),
E('chasten','/ˈtʃeɪsən/','使受到教训；使收敛；使懊悔','原来觉得自己肯定没问题，结果碰了壁，于是傲气落下来，开始认真反省。','英语旧动词 chaste 惩戒加 -en；旧动词经法语接拉丁 castigare。不是简单把现代 chaste 贞洁变成使贞洁。',CHASTEN,'be chastened by a defeat 是被失败教训了、变得谨慎。主语可以是一个经历，不必真的有人训话。t 在常用读法里不发音。','be chastened by；a chastening experience；chasten somebody。','chastise 强调训斥的动作；chasten 强调让人受到教训、收敛的效果，失败本身也能做到。',('The unexpected defeat chastened the confident team.','意外失利让原本自信的球队收敛了傲气。'),('He was chastened by the realization that he had blamed the wrong person.','意识到自己错怪了人，他感到惭愧并收敛了态度。'),sources=['https://www.etymonline.com/word/chasten','https://www.oxfordlearnersdictionaries.com/definition/english/chasten']),
E('chastened','/ˈtʃeɪsənd/','受到教训而收敛的；懊悔的','不是单纯不高兴，而是经历过一次打击或批评后，姿态放低了。','chasten + -ed，过去分词常作形容词；保留受教训后改变心态的结果。',CHASTEN+[['英语 chasten → chastened','从使受到教训到已收敛、懊悔的状态']],'a chastened response 是收敛后的回应；look chastened 是看起来知道错了。它可以包含惭愧，但不要求已经彻底改过。','look chastened；a chastened mood；a chastened response。','ashamed 强调羞愧；chastened 还带受到现实或批评教育过、没那么自负的意味。',('A chastened spokesperson admitted that the figures were wrong.','发言人态度收敛，承认那些数字有误。'),('The players returned to training in a chastened mood.','球员们带着受过教训后的谨慎心态回到训练中。'),sources=['https://www.etymonline.com/word/chasten','https://www.oxfordlearnersdictionaries.com/definition/english/chasten']),
E('castrate','英 /kæˈstreɪt/；美 /ˈkæstreɪt/','阉割；使失去力量〔比喻〕','本义是去除雄性的睾丸；比喻时说把某个机构的实际力量削掉。','接拉丁 castrare、其分词 castratus，也可能从更早进入英语的 castration 逆构。它与 castus 的远源联系有讨论，不能直说纯洁产生阉割。',CASTR+[['拉丁 castratus；或英语 castration 的逆构 → castrate','两种历史解释；现代动词有字面和削弱力量的比喻义']],'兽医或历史文本中常见字面义；politically castrated 一类说法是强烈比喻。普通工作表达用 weaken 或 strip of power 更自然。','castrate an animal；a castrated male；politically castrated。','neuter 是更广的绝育词；castrate 在常见字面用法中特别指雄性去势，不能和任何绝育方式都画等号。',('The record states that the male animal had been castrated.','记录注明这只雄性动物已被阉割。'),('Critics argued that the amendment would castrate the watchdog agency.','批评者认为，这项修正案会使监管机构失去实际力量。'),sources=['https://www.etymonline.com/word/castrate','https://www.oxfordlearnersdictionaries.com/definition/english/castrate']),
E('castration','/kæˈstreɪʃən/','阉割；去势','把去除或抑制性腺功能这一过程作为名词来谈，常见于兽医、医学和历史。','经中古法语或直接借拉丁 castratio，来自 castrare；英语 castration 的记录早于 castrate 动词，现代可互认词形，但不要倒写历史。',CASTR+[['拉丁 castratio；中古法语 castration → 中古英语 castracioun → castration','先借入过程名词；后来英语出现相应动词']],'surgical castration 指手术去势；chemical castration 是使用药物抑制相关功能的名称，并不意味着手术切除。日常读文章时，先看限定词再理解具体所指。','surgical castration；chemical castration；a history of castration。','sterilization 强调失去生育能力；castration 牵涉性腺或其功能，范围与作用并不完全相同。',('The textbook distinguishes surgical castration from chemical castration.','教材区分了手术去势和药物去势。'),('The museum label discusses the historical use of castration in animal husbandry.','博物馆说明牌介绍了畜牧业中阉割的历史用途。'),sources=['https://www.etymonline.com/word/castration','https://www.merriam-webster.com/dictionary/castration']),
]
Path('.cache/batch200/st42-working-words.json').write_text(json.dumps(W,ensure_ascii=False,indent=2)+'\n')
print('st42 working',len(W))
W += [
E('detriment','/ˈdetrɪmənt/','损害；不利因素','本来好好的一部分被磨掉了，因此利益、能力或状态受了损。','拉丁 de- 离去 + terere 磨，形成 deterere、detrimentum；经法语或直接拉丁路线进入英语。',DETR,'to the detriment of somebody 是以损害某人的利益为代价；without detriment to something 是不损害某事。a detriment 也可以指造成坏影响的因素。','to the detriment of；without detriment to；a detriment to。','damage 常直接说损坏；detriment 更常见于正式表达，强调利益或效果受到不利影响。',('He pursued speed to the detriment of accuracy.','他追求速度，却牺牲了准确性。'),('The change can be made without detriment to service quality.','这项调整可以在不损害服务质量的情况下完成。'),sources=['https://www.etymonline.com/word/detriment','https://en.wiktionary.org/wiki/detriment#English']),
E('detrimental','/ˌdetrɪˈmentəl/','有害的；不利的','描述一件事会让另一件事变差：不是没有帮助，而是真的造成损失。','现代对应 detriment + -al；历史也联系拉丁及中世纪拉丁相关形容词形式。英语常用义是造成损害的。',DETR+[['英语 detriment 与 -al 形容词形式 → detrimental','由损害转成造成损害的性质']],'be detrimental to something 是对某事有害。这个 to 是介词，后面接名词或动名词，不能套成 detrimental for doing 的固定模板。','be detrimental to；a detrimental effect；prove detrimental。','ineffective 是没有效果；detrimental 是有负面效果。一次低效会议未必已经对项目造成实质损害。',('Constant interruptions are detrimental to concentration.','不断被打断不利于集中注意力。'),('The delay had a detrimental effect on the launch.','延误对发布造成了不利影响。'),sources=['https://www.etymonline.com/word/detrimental','https://en.wiktionary.org/wiki/detrimental#English']),
E('detrimentally','/ˌdetrɪˈmentəli/','有害地；产生不利影响地','用来说明影响的方向是变坏，常跟 affect 一起出现。','detrimental + -ly；保留原有重音，把有害的性质改成动作或影响的方式。',DETR+[['英语 detriment + -al → detrimental；再加 -ly → detrimentally','损害 → 有害的 → 以有害的方式']],'detrimentally affect performance 是对表现产生不利影响；常见于报告、研究和正式分析。日常可直接说 harm 或 have a bad effect on。','detrimentally affect；be detrimentally affected；impact detrimentally on。','detrimental 修饰名词，如 detrimental effects；detrimentally 修饰动作，不能说 a detrimentally effect。',('The repeated outages detrimentally affected customer trust.','反复停机损害了客户的信任。'),('Small suppliers were detrimentally affected by the abrupt change.','小型供应商受到这次突然调整的不利影响。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/detrimentally','https://www.etymonline.com/word/detrimental']),
E('attrition','/əˈtrɪʃən/','逐步损耗；人员自然流失；消耗战式削弱','不是一下子打掉，而是一点点磨掉：每次少一些，累积起来就很明显。','拉丁 ad- 朝向与 terere 磨形成 atterere，再有 attritio；借入英语的名词很早，不能倒推为后来英语 attrit 动词加 -ion。',TER+[['拉丁 atterere 磨损 → attritio → 英语 attrition','早期也有宗教悔罪义；物理磨损逐渐扩展为力量与人员损耗']],'a war of attrition 是靠持续消耗对方力量来取胜；公司 reduce staff through attrition 通常是有人离职或退休后不补缺，不等同于直接裁员。研究中的 participant attrition 指参与者逐渐退出。','a war of attrition；staff attrition；customer attrition；attrition rate。','layoffs 是主动裁员；natural attrition 是自然离开造成的减员。研究里的 attrition 关注样本流失，未必涉及就业。',('The company reduced its headcount through natural attrition.','公司通过自然减员缩减了员工人数。'),('Participant attrition made the final survey sample smaller.','参与者陆续退出，使最终调查样本缩小了。'),sources=['https://www.etymonline.com/word/attrition','https://dictionary.cambridge.org/dictionary/english/attrition']),
E('attritional','/əˈtrɪʃənəl/','消耗性的；靠逐步削弱取胜的','一场较量迟迟没有突破，双方只好不断消耗时间、体力或资源。','attrition + -al；把逐步损耗变成形容词，常用于战争、竞争和漫长的比赛。',TER+[['拉丁 atterere → attritio → 英语 attrition；再加 -al → attritional','磨损、损耗 → 以持续消耗为特点']],'attritional warfare 是消耗战；an attritional contest 是双方长时间磨下去的较量。它不是一般持续很久，而是长久竞争中伴随损耗。','attritional warfare；an attritional battle；an attritional contest。','prolonged 只说时间拖长；attritional 还强调力量或资源被逐步消耗。',('The match became an attritional contest in the final hour.','比赛最后一小时变成了一场消耗体力的拉锯战。'),('The historian contrasts rapid advances with attritional warfare.','历史学家对比了快速推进与消耗战。'),sources=['https://en.wiktionary.org/wiki/attritional#English','https://www.etymonline.com/word/attrition']),
E('trite','/traɪt/','陈词滥调的；老套的','一句话被反复用到失去棱角，听者一听开头就知道后面是什么。','借拉丁 tritus 磨旧的，terere 的过去分词；拉丁语中已经有语言用得太多的引申，不是英语才发明这一比喻。',TER+[['拉丁 tritus 磨旧的、说惯的 → 英语 trite','被反复使用而失去新意']],'a trite remark 是老套的话；a trite ending 是俗套结尾。问题在表达被用滥，不一定在观点本身错误。','a trite phrase；a trite remark；sound trite。','simple 是简单，trite 是因重复太多而乏味；一句简单却准确的话不必是 trite。',('The speech relied on trite phrases about success.','演讲依赖一些关于成功的陈词滥调。'),('The ending felt trite, although the acting was excellent.','尽管表演出色，结尾还是显得老套。'),sources=['https://www.etymonline.com/word/trite','https://en.wiktionary.org/wiki/trite#English']),
E('triteness','/ˈtraɪtnəs/','老套；陈腐乏味','把让人觉得又是这一套的那种性质单独拿出来评价。','trite + -ness；不改变 trite 的主重音，由形容词转成不可数抽象名词。',TER+[['拉丁 tritus → 英语 trite；trite + -ness → triteness','磨掉新鲜感的表达 → 老套这一性质']],'the triteness of a slogan 是一句口号的陈腐；avoid triteness 是避开陈词滥调。它不是表示许多老套句子的普通复数集合名词。','the triteness of；avoid triteness；criticize the triteness。','a cliché 是一句或一种具体的陈词滥调；triteness 是老套的性质，常搭配不可数用法。',('The reviewer criticized the triteness of the dialogue.','评论者批评了对白的陈腐。'),('Specific details can help a personal essay avoid triteness.','具体细节可以帮助个人随笔避免落入俗套。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/triteness','https://www.etymonline.com/word/trite']),
E('detritus','/dɪˈtraɪtəs/','碎屑；残渣；零散废物','原本较完整的东西磨损、破碎或腐败后，留下细碎的残余。','接拉丁 deterere 磨掉、detritus；现代碎屑义通常经法语 détritus 解释。英语早期还用来指侵蚀过程，不能仅按现代意思硬拆词尾。',TER+[['拉丁 deterere、detritus → 法语 détritus → 英语 detritus','磨损相关名称成为岩石碎屑名词；也泛指有机碎屑和杂物']],'rock detritus 是岩石碎屑；organic detritus 是动植物遗体等分解留下的有机碎屑。日常书面语也可说桌上、海滩上的零散残物。','organic detritus；rock detritus；the detritus of daily life。','debris 更泛指碎片、残骸；detritus 常强调零碎残余或磨损、分解后的材料，不必都是人丢弃的垃圾。',('Organic detritus collected at the bottom of the pond.','有机碎屑聚集在池塘底部。'),('The desk was covered with the detritus of a week of hurried work.','桌上堆满了一周匆忙工作留下的零散杂物。'),sources=['https://www.merriam-webster.com/dictionary/detritus','https://www.etymonline.com/word/detritus']),
E('contrite','/kənˈtraɪt/','悔恨的；深感歉疚的','意识到是自己伤害了别人，心里压着分量，想真诚认错。','来自古法语 contrit 或直接借拉丁 contritus；本来是磨碎的，教会拉丁语用来比喻因过错而内心受压、悔罪。',CONTRITE,'a contrite apology 是带着真切悔意的道歉；look contrite 是看起来十分懊悔。它比随口说 sorry 更郑重。','a contrite apology；look contrite；a contrite expression。','regretful 可以只是遗憾结果不好；contrite 通常承认自己有过错，带着歉疚。',('He sounded genuinely contrite when he apologized.','他道歉时听起来确实十分懊悔。'),('She sent a contrite note after realizing how much her words had hurt him.','意识到自己的话伤他很深后，她发去了一封诚恳认错的短笺。'),sources=['https://www.etymonline.com/word/contrite','https://en.wiktionary.org/wiki/contrite#English']),
E('contrition','/kənˈtrɪʃən/','悔恨；悔罪；深切歉疚','关注的不是一句道歉说了什么，而是里面是否真的有认错的心。','晚期拉丁 contritio 悔罪、悲痛，经古法语 contriciun 或直接借入；它与 contrite 是同根借词，不是现代英语才把 contrite 改成 -ion。',CONTR+[['晚期拉丁 contritio → 古法语 contriciun 或直接借入 → 英语 contrition','磨碎的比喻发展为深切悔意的名词']],'show contrition 是表现出悔意；a lack of contrition 是缺乏悔意。宗教中的 act of contrition 也可指特定的认罪祈祷。','show contrition；express contrition；a lack of contrition。','apology 是表达歉意的行为或话语；contrition 是内在悔意，有道歉话语不一定就有 contrition。',('The letter expressed contrition without making excuses.','那封信表达了悔意，没有找借口。'),('Her willingness to repair the damage showed real contrition.','她愿意弥补损害，显示出真切的悔意。'),sources=['https://www.etymonline.com/word/contrition','https://en.wiktionary.org/wiki/contrition#English']),
E('contritely','/kənˈtraɪtli/','懊悔地；带着歉疚地','说话或做事时，明显带着我知道自己错了的态度。','contrite + -ly；读音保留 contrite 的 /aɪ/，不同于 contrition 中的 /ɪ/。',CONTRITE+[['英语 contrite + -ly → contritely','以悔恨、歉疚的态度行动']],'apologize contritely 是诚恳而懊悔地道歉；admit something contritely 是带着歉疚承认。它修饰态度，不自动证明之后一定会改正。','apologize contritely；admit contritely；say contritely。','politely 只说明有礼貌；contritely 说明有悔意。两者可以同时出现，但不能互换。',('"I should have listened," he admitted contritely.','他懊悔地承认，自己当时应该认真听。'),('She apologized contritely for dismissing their concerns.','她为之前不把他们的担忧当回事而懊悔地道歉。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/contritely','https://www.etymonline.com/word/contrite']),
]
